export interface OutlineNode {
  id: string;
  label: string;
  icon?: string;
  children?: readonly OutlineNode[];
}

export interface OutlineRow {
  id: string;
  label: string;
  icon?: string;
  depth: number;
  className: string;
}

export function flattenOutline(
  nodes: readonly OutlineNode[],
  openIds: ReadonlySet<string>,
  prefix: string,
): OutlineRow[] {
  if (!prefix) throw new RangeError("prefix must not be empty");
  const ids = new Set<string>();
  const active = new WeakSet<object>();

  const validate = (node: OutlineNode): void => {
    if (active.has(node)) throw new RangeError("cyclic outline");
    active.add(node);
    const id = node.id.trim();
    if (!id || !node.label.trim()) throw new RangeError("invalid node");
    if (ids.has(id)) throw new RangeError("duplicate node id");
    ids.add(id);
    for (const child of node.children ?? []) validate(child);
    active.delete(node);
  };
  for (const node of nodes) validate(node);

  const rows: OutlineRow[] = [];
  const visit = (node: OutlineNode, depth: number): void => {
    const id = node.id.trim();
    const icon = node.icon?.trim() || undefined;
    rows.push({ id, label: node.label.trim(), icon, depth, className: `${prefix}node` });
    if (openIds.has(id)) {
      for (const child of node.children ?? []) visit(child, depth);
    }
  };
  for (const node of nodes) visit(node, 0);
  return rows;
}

