import { flattenOutline, type OutlineNode } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const nodes: OutlineNode[] = [{
  id: ' root ', label: ' Root ', icon: ' folder ', children: [
    { id: 'child', label: ' Child ', icon: '   ', children: [
      { id: 'grand', label: ' Grand' },
    ] },
  ],
}, { id: 'second', label: ' Second ' }];
const openIds = new Set(['root', 'child']);
const rows = flattenOutline(nodes, openIds, 'tree-');
deepEqual(rows, [
  { id: 'root', label: 'Root', icon: 'folder', depth: 0, className: 'tree-node' },
  { id: 'child', label: 'Child', icon: undefined, depth: 1, className: 'tree-node' },
  { id: 'grand', label: 'Grand', icon: undefined, depth: 2, className: 'tree-node' },
  { id: 'second', label: 'Second', icon: undefined, depth: 0, className: 'tree-node' },
], 'visible preorder, depth, trimming, and class name');
assert(openIds.size === 2 && openIds.has('root'), 'openIds is not mutated');
assert(nodes[0].id === ' root ' && nodes[0].label === ' Root ', 'nodes are not mutated');
rows[0].label = 'Changed';
assert(nodes[0].label === ' Root ', 'rows are fresh objects');

deepEqual(flattenOutline(nodes, new Set<string>(), 'x'), [
  { id: 'root', label: 'Root', icon: 'folder', depth: 0, className: 'xnode' },
  { id: 'second', label: 'Second', icon: undefined, depth: 0, className: 'xnode' },
], 'closed roots hide descendants');
deepEqual(flattenOutline([], new Set<string>(), 'p'), [], 'empty nodes');
throwsRangeError(() => flattenOutline([], new Set<string>(), ''), 'empty prefix');

const hiddenInvalid: OutlineNode[] = [{
  id: 'closed', label: 'Closed', children: [{ id: 'bad', label: '   ' }],
}];
throwsRangeError(() => flattenOutline(hiddenInvalid, new Set<string>(), 'p'), 'hidden descendants are validated');

throwsRangeError(() => flattenOutline([
  { id: ' duplicate ', label: 'One' },
  { id: 'duplicate', label: 'Two' },
], new Set<string>(), 'p'), 'trimmed ids are globally unique');
throwsRangeError(() => flattenOutline([{ id: ' ', label: 'x' }], new Set<string>(), 'p'), 'empty id');

const cyclic: OutlineNode = { id: 'cycle', label: 'Cycle' };
cyclic.children = [cyclic];
throwsRangeError(() => flattenOutline([cyclic], new Set(['cycle']), 'p'), 'cyclic object references');

